export class EventLog {
  constructor(private persistence: EventPersistence) {}

  async append(event: AgentEvent): Promise<void> {
    // Validate event
    if (!event.runId || !event.agentId || !event.type) {
      throw new Error("Invalid event: missing required fields")
    }

    event.timestamp = event.timestamp || new Date().toISOString()

    // Persist
    await this.persistence.append(event.runId, event)

    // Emit for subscribers (real-time)
    this.emit("event", event)
  }

  async listEvents(
    runId: string,
    options?: { agentId?: string; afterSequence?: number }
  ): Promise<AgentEvent[]> {
    return this.persistence.query(runId, options)
  }

  async getRunSummary(runId: string): Promise<RunSummary> {
    const events = await this.persistence.query(runId)

    const summary: RunSummary = {
      runId,
      status: "unknown",
      agentCount: new Set(events.map((e) => e.agentId)).size,
      toolCount: events.filter((e) => e.type === "tool.completed").length,
      startTime: events[0]?.timestamp,
      endTime: events[events.length - 1]?.timestamp,
      events: events.length,
    }

    const lastEvent = events[events.length - 1]
    if (lastEvent?.type === "run.completed") {
      summary.status = "completed"
    } else if (lastEvent?.type === "run.failed") {
      summary.status = "failed"
    } else if (lastEvent?.type === "run.cancelled") {
      summary.status = "cancelled"
    } else if (events.some((e) => e.type === "run.started")) {
      summary.status = "running"
    }

    return summary
  }

  private emit(eventName: string, data: any): void {
    // EventEmitter implementation
  }
}

export interface RunSummary {
  runId: string
  status: "unknown" | "running" | "completed" | "failed" | "cancelled"
  agentCount: number
  toolCount: number
  startTime?: string
  endTime?: string
  events: number
}

export interface EventPersistence {
  append(runId: string, event: AgentEvent): Promise<void>
  query(
    runId: string,
    options?: { agentId?: string; afterSequence?: number }
  ): Promise<AgentEvent[]>
  deleteRun(runId: string): Promise<void>  // Retention policy
}
