```typescript
import * as fs from "fs/promises"
import * as path from "path"

export class FileEventStore implements EventPersistence {
  private basePath: string

  constructor(basePath: string = ".axiom/runs") {
    this.basePath = basePath
  }

  async append(runId: string, event: AgentEvent): Promise<void> {
    const dir = path.join(this.basePath, runId)
    await fs.mkdir(dir, { recursive: true })

    const filePath = path.join(dir, "events.jsonl")

    // Append-only: add event as new line
    const line = JSON.stringify(event) + "\n"
    await fs.appendFile(filePath, line, "utf-8")
  }

  async query(
    runId: string,
    options?: { agentId?: string; afterSequence?: number }
  ): Promise<AgentEvent[]> {
    const filePath = path.join(this.basePath, runId, "events.jsonl")

    try {
      const content = await fs.readFile(filePath, "utf-8")
      const events = content
        .split("\n")
        .filter((line) => line.trim())
        .map((line) => JSON.parse(line) as AgentEvent)

      // Filter if requested
      if (options?.agentId) {
        return events.filter((e) => e.agentId === options.agentId)
      }

      if (options?.afterSequence !== undefined) {
        return events.filter((e) => e.sequence > options.afterSequence!)
      }

      return events
    } catch (error) {
      if ((error as any).code === "ENOENT") {
        return []  // Run doesn't exist yet
      }
      throw error
    }
  }

  async deleteRun(runId: string): Promise<void> {
    const dir = path.join(this.basePath, runId)
    await fs.rm(dir, { recursive: true, force: true })
  }
}
