```typescript
// src/store/slices/createAgentSlice.ts

export const createAgentSlice = (set, get) => ({
  // ... existing state

  // Recover run from event log
  async recoverRun(runId: string) {
    const response = await fetch(`/api/runs/${runId}/events`)
    const events = await response.json()

    // Replay events to reconstruct state
    const messages: Message[] = []
    let status = "unknown"
    const subagents: SubagentRecord[] = []

    for (const event of events) {
      switch (event.type) {
        case "run.started":
          messages.push({
            type: "user",
            content: event.payload.task,
          })
          status = "running"
          break

        case "token":
          if (messages[messages.length - 1]?.type === "assistant") {
            messages[messages.length - 1].content += event.payload.token
          } else {
            messages.push({
              type: "assistant",
              content: event.payload.token,
            })
          }
          break

        case "agent.spawned":
          subagents.push({
            id: event.payload.agentId,
            objective: event.payload.objective,
            status: "running",
          })
          break

        case "run.completed":
          status = "completed"
          break

        case "run.failed":
          status = "failed"
          break
      }
    }

    set({
      chats: {
        ...get().chats,
        [runId]: {
          id: runId,
          messages,
          status,
          subagents,
        },
      },
    })
  },
})
