export class DelegationInputBuilder {
  static buildFromPrompt(
    prompt: string,
    codebaseContext: CodebaseContext
  ): DelegatedTask {
    // Use LLM to extract structured task from prose
    // Fallback to heuristics if unavailable

    const task = this.parsePrompt(prompt)

    // Auto-detect scope if not specified
    if (!task.scope || task.scope.length === 0) {
      task.scope = this.inferScope(prompt, codebaseContext)
    }

    // Validate scope exists
    this.validateScope(task.scope, codebaseContext)

    return task
  }

  static async getRecommendedScope(
    objective: string,
    codebaseContext: CodebaseContext
  ): Promise<string[]> {
    // Semantic search or keyword matching to suggest relevant files
    const matches = await codebaseContext.search(objective)
    return matches.slice(0, 10).map((m) => m.path)
  }

  private static parsePrompt(prompt: string): Partial<DelegatedTask> {
    // Heuristics for parsing scope, expected output, etc.
    // e.g., "investigate src/auth for security" → scope: ["src/auth"]

    return {
      objective: prompt,
      expectedOutput: "findings",
      evidenceRequired: true,
      maxTurns: 8,
      timeoutMs: 120000,
    }
  }

  private static inferScope(prompt: string, context: CodebaseContext): string[] {
    // Keyword-based scope inference
    const keywords = this.extractKeywords(prompt)
    const relevant = context.files.filter((f) =>
      keywords.some((k) => f.path.toLowerCase().includes(k.toLowerCase()))
    )
    return relevant.slice(0, 5).map((f) => f.path)
  }

  private static extractKeywords(prompt: string): string[] {
    // Extract nouns and module names from prompt
    return ["auth", "user", "security"] // Simplified
  }

  private static validateScope(scope: string[], context: CodebaseContext): void {
    for (const path of scope) {
      if (!context.fileExists(path)) {
        throw new Error(`Scope path does not exist: ${path}`)
      }
    }
  }
}
