import React, { useState } from "react"
import { DelegationResult } from "../protocol/messageTypes"

export interface DelegationRecord {
  agentId: string
  objective: string
  scope: string[]
  status: "pending" | "running" | "completed" | "failed"
  result?: DelegationResult
  spawnedAt: Date
  completedAt?: Date
}

export function DelegationPanel({ delegations }: { delegations: DelegationRecord[] }) {
  const [expanded, setExpanded] = useState<Set<string>>(new Set())
  const [filter, setFilter] = useState<"all" | "completed" | "pending">("all")

  const filtered = delegations.filter((d) => {
    if (filter === "all") return true
    if (filter === "completed") return d.status === "completed"
    if (filter === "pending") return d.status === "pending" || d.status === "running"
    return true
  })

  return (
    <div className="delegation-panel">
      <div className="header">
        <h3>Delegated Investigations ({filtered.length})</h3>
        <div className="filters">
          <button
            onClick={() => setFilter("all")}
            className={filter === "all" ? "active" : ""}
          >
            All
          </button>
          <button
            onClick={() => setFilter("pending")}
            className={filter === "pending" ? "active" : ""}
          >
            Pending
          </button>
          <button
            onClick={() => setFilter("completed")}
            className={filter === "completed" ? "active" : ""}
          >
            Completed
          </button>
        </div>
      </div>

      <div className="delegations-list">
        {filtered.map((delegation) => (
          <DelegationCard
            key={delegation.agentId}
            delegation={delegation}
            isExpanded={expanded.has(delegation.agentId)}
            onToggle={() => {
              const newSet = new Set(expanded)
              if (newSet.has(delegation.agentId)) {
                newSet.delete(delegation.agentId)
              } else {
                newSet.add(delegation.agentId)
              }
              setExpanded(newSet)
            }}
          />
        ))}
      </div>
    </div>
  )
}

function DelegationCard({
  delegation,
  isExpanded,
  onToggle,
}: {
  delegation: DelegationRecord
  isExpanded: boolean
  onToggle: () => void
}) {
  const statusIcon = {
    pending: "⏳",
    running: "▶️",
    completed: "✓",
    failed: "✗",
  }[delegation.status]

  return (
    <div className="delegation-card">
      <div className="card-header" onClick={onToggle}>
        <span className="status-icon">{statusIcon}</span>
        <span className="objective">{delegation.objective}</span>
        <span className="time">
          {delegation.completedAt
            ? `${Math.round((delegation.completedAt.getTime() - delegation.spawnedAt.getTime()) / 1000)}s`
            : `Started ${this.formatTime(delegation.spawnedAt)}`}
        </span>
      </div>

      {isExpanded && (
        <div className="card-body">
          <div className="scope">
            <strong>Scope:</strong>
            <ul>
              {delegation.scope.map((path) => (
                <li key={path}>{path}</li>
              ))}
            </ul>
          </div>

          {delegation.result && (
            <div className="result">
              <strong>Findings:</strong>
              <p>{delegation.result.findings}</p>

              <div className="metadata">
                <span>Turns: {delegation.result.metadata.turnsUsed}</span>
                <span>Tokens: {delegation.result.metadata.tokensUsed}</span>
                <span>Tools: {delegation.result.metadata.toolsCalled.join(", ")}</span>
              </div>
            </div>
          )}

          {delegation.status === "running" && <div className="spinner">Investigating...</div>}

          {delegation.status === "failed" && (
            <div className="error">Investigation failed. Check logs for details.</div>
          )}
        </div>
      )}
    </div>
  )
}
