export class Telemetry {
  private runs: Map<string, RunTelemetry> = new Map()
  private currentRequest?: RequestMetrics

  trackRequest(type: string, payloadSize: number): RequestMetricsTracker {
    const metrics: RequestMetrics = {
      requestId: generateUUID(),
      type,
      startTime: Date.now(),
      payloadSize,
      success: false,
      retryCount: 0,
    }

    this.currentRequest = metrics

    return {
      success: (responseSize: number) => {
        metrics.endTime = Date.now()
        metrics.duration = metrics.endTime - metrics.startTime
        metrics.success = true
        metrics.responseSize = responseSize
        this.recordMetrics(metrics)
      },
      error: (error: Error) => {
        metrics.endTime = Date.now()
        metrics.duration = metrics.endTime - metrics.startTime
        metrics.error = error.message
        this.recordMetrics(metrics)
      },
      retry: () => {
        metrics.retryCount++
      },
    }
  }

  private recordMetrics(metrics: RequestMetrics): void {
    // Emit event for subscribers
    this.emit("request", metrics)

    // Write to persistent log if runId available
    if (this.currentRequest?.requestId) {
      // ...
    }
  }
}

interface RequestMetricsTracker {
  success(responseSize: number): void
  error(error: Error): void
  retry(): void
}
