#### Backpressure Handling

```typescript
export class BoundedQueue<T> {
  private queue: T[] = []
  private maxSize: number
  private drainHandlers: (() => void)[] = []

  constructor(maxSize: number = 1000) {
    this.maxSize = maxSize
  }

  async push(item: T): Promise<void> {
    return new Promise((resolve) => {
      this.queue.push(item)

      if (this.queue.length >= this.maxSize) {
        // Wait for drain before resolving
        this.drainHandlers.push(resolve)
      } else {
        resolve()
      }
    })
  }

  pop(count: number = 1): T[] {
    const items = this.queue.splice(0, count)

    // Notify waiting pushers if queue is now below threshold
    if (items.length > 0 && this.queue.length < this.maxSize * 0.8) {
      const handlers = this.drainHandlers.splice(0)
      handlers.forEach((h) => h())
    }

    return items
  }

  size(): number {
    return this.queue.length
  }
}

// WebSocket backpressure
ws.on("drain", () => {
  // Resume sending when buffer space available
  if (tokenQueue.size() > 0) {
    const tokens = tokenQueue.pop(10)
    for (const token of tokens) {
      ws.write(token)
    }
  }
})
